SELECT om.maintcost, CAST(om.revloss AS text), 
       ROUND(CAST(om.maintcost AS numeric) / NULLIF(CAST(REPLACE(REPLACE(om.revloss, '$', ''), ',', '') AS numeric), 2) AS ratio
FROM operational_metrics om JOIN plant_record pr ON om.snapops = pr.snapkey WHERE pr.sitetie = 'SP3459';

SELECT om.maintcost, CAST(om.revloss AS text), 
       ROUND(CAST(om.maintcost AS numeric) / NULLIF(CAST(REPLACE(REPLACE(om.revloss, '$', ''), ',', '') AS numeric), 2)) AS ratio
FROM operational_metrics om JOIN plant_record pr ON om.snapops = pr.snapkey WHERE pr.sitetie = 'SP3459';

SELECT ROUND(CAST(SUM(om.maintcost) AS numeric) / NULLIF(CAST(SUM(CAST(REPLACE(REPLACE(om.revloss, '$', ''), ',', '') AS numeric)) AS numeric), 2) AS maint_to_rev_ratio
